// Abstract class SortAlgorithm with template method sort()
public abstract class SortAlgorithm {
    public abstract void sort(int[] array);
    public abstract void compare(int[] array);
    public abstract void swap(int[] array, int i, int j);
}

// Concrete subclass BubbleSort
public class BubbleSort extends SortAlgorithm {
    @Override
    public void sort(int[] array) {
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = 0; j < array.length - i - 1; j++) {
                if (compare(array, j) > 0) {
                    swap(array, j, j + 1);
                }
            }
        }
    }

    @Override
    public void compare(int[] array) {
        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] > array[i + 1]) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

